#!/usr/bin/env bash
set -e
mkdir -p 'voordedag-app/app'
cat > 'voordedag-app/app/globals.css' <<'__PATCH_000__'
:root{--nacht: #16233a;--nacht-2: #22324f;--warmwit: #fffdf7;--geel: #ffd84d;--lucht: #dceeff;--slate: #667085;--soft: #f5f7fa;--wit: #ffffff;--line: #e4e7ec;--line-strong: #cfd5df;--error: #b42318;--success: #067647;--font-display: var(--font-manrope),system-ui,sans-serif;--font-body: var(--font-inter),system-ui,sans-serif;--container: 1200px;--gutter: clamp(20px,5vw,32px);--section: clamp(64px,9vw,120px);--radius: 16px;--radius-btn: 12px;--ease: cubic-bezier(0.22,1,0.36,1);--t-ui: 220ms;--t-reveal: 520ms;--header-h: 72px}*,*::before,*::after{box-sizing: border-box}html{-webkit-text-size-adjust: 100%;scroll-padding-top: calc(var(--header-h) + 16px)}body{margin: 0;background: var(--warmwit);color: var(--nacht);font-family: var(--font-body);font-size: 16px;line-height: 1.6;text-rendering: optimizeLegibility;-webkit-font-smoothing: antialiased;overflow-x: clip;overflow-wrap: break-word}h1,h2,h3{hyphens: auto;-webkit-hyphens: auto}@media (min-width: 768px){body{font-size: 17px}}img,svg{display: block;max-width: 100%}a{color: inherit}button,input,select,textarea{font: inherit;color: inherit}p{margin: 0 0 1em}p:last-child{margin-bottom: 0}h1,h2,h3,h4,.display{font-family: var(--font-display);font-weight: 750;letter-spacing: -0.025em;margin: 0 0 0.5em;text-wrap: balance}.display{font-size: clamp(2.5rem,1.6rem + 3.9vw,4rem);line-height: 1.06;letter-spacing: -0.035em;font-weight: 800}h1{font-size: clamp(2.375rem,1.9rem + 2.1vw,3.25rem);line-height: 1.08;letter-spacing: -0.03em}h2{font-size: clamp(2rem,1.7rem + 1.3vw,2.5rem);line-height: 1.12}h3{font-size: clamp(1.375rem,1.25rem + 0.6vw,1.75rem);line-height: 1.2;letter-spacing: -0.015em}h4{font-size: 1.125rem;line-height: 1.3;letter-spacing: -0.01em;font-weight: 700}.intro{font-size: clamp(1.125rem,1.05rem + 0.35vw,1.25rem);line-height: 1.55;color: var(--nacht);max-width: 38em}.muted{color: var(--slate)}.small{font-size: 0.875rem}.container{width: 100%;max-width: calc(var(--container) + 2 * var(--gutter));margin: 0 auto;padding-inline: var(--gutter)}.section{padding-block: var(--section)}.section--lucht{background: var(--lucht);--slate: #4b5669}.section--soft{background: var(--soft)}.section--nacht{background: var(--nacht);color: var(--wit)}.section--nacht .muted{color: #b9c3d6}.stack>* + *{margin-top: 1rem}.measure{max-width: 40em}.skip-link{position: absolute;left: 12px;top: -100px;z-index: 100;background: var(--nacht);color: var(--wit);padding: 12px 16px;border-radius: 10px;text-decoration: none}.skip-link:focus{top: 12px}:focus-visible{outline: 3px solid var(--nacht);outline-offset: 3px;border-radius: 4px}.section--nacht :focus-visible,.footer :focus-visible{outline-color: var(--geel)}.sr-only{position: absolute;width: 1px;height: 1px;padding: 0;margin: -1px;overflow: hidden;clip: rect(0,0,0,0);white-space: nowrap;border: 0}.btn{display: inline-flex;align-items: center;justify-content: center;gap: 10px;min-height: 50px;padding: 0 22px;border-radius: var(--radius-btn);font-family: var(--font-body);font-size: 16px;font-weight: 600;line-height: 1.2;text-decoration: none;border: 1.5px solid transparent;cursor: pointer;transition: background-color var(--t-ui) var(--ease),color var(--t-ui) var(--ease),border-color var(--t-ui) var(--ease),transform 120ms var(--ease);-webkit-tap-highlight-color: transparent;text-align: center}.btn:active{transform: translateY(1px)}.btn--primary{background: var(--nacht);color: var(--wit)}.btn--primary:hover{background: var(--nacht-2)}.btn--secondary{background: transparent;color: var(--nacht);border-color: var(--line-strong)}.btn--secondary:hover{border-color: var(--nacht);background: var(--wit)}.btn--geel{background: var(--geel);color: var(--nacht)}.btn--geel:hover{background: #ffe27a}.btn--light{background: var(--wit);color: var(--nacht)}.btn--light:hover{background: var(--warmwit)}.btn[disabled]{opacity: 0.6;cursor: progress}.btn-row{display: flex;flex-wrap: wrap;gap: 12px}@media (max-width: 479px){.btn-row .btn{width: 100%}}.textlink{font-weight: 600;text-decoration: underline;text-decoration-thickness: 1.5px;text-underline-offset: 4px;text-decoration-color: var(--geel);transition: text-decoration-color var(--t-ui)}.textlink:hover{text-decoration-color: currentColor}.logo{display: inline-flex;align-items: center;text-decoration: none;color: inherit}.wordmark{font-family: var(--font-display);font-weight: 800;letter-spacing: -0.045em;font-size: 1.5rem;line-height: 1;white-space: nowrap;display: inline-flex;align-items: baseline}.wordmark__dag{position: relative;padding-bottom: 0.2em;margin-bottom: -0.2em;-webkit-mask-image: linear-gradient(to bottom,#000 0 60%,transparent 60% 63.75%,#000 63.75%);mask-image: linear-gradient(to bottom,#000 0 60%,transparent 60% 63.75%,#000 63.75%)}.wordmark__space{width: 0.24em;display: inline-block}.header{position: sticky;top: 0;z-index: 50;background: color-mix(in srgb,var(--warmwit) 92%,transparent);backdrop-filter: saturate(1.4) blur(10px);-webkit-backdrop-filter: saturate(1.4) blur(10px);border-bottom: 1px solid transparent;transition: border-color var(--t-ui)}.header[data-scrolled="true"]{border-bottom-color: var(--line)}.header__inner{height: var(--header-h);display: flex;align-items: center;justify-content: space-between;gap: 24px}.header__nav{display: none}.header__nav ul{display: flex;gap: 4px;list-style: none;margin: 0;padding: 0}.header__nav a{display: inline-flex;align-items: center;min-height: 44px;padding: 0 14px;border-radius: 10px;text-decoration: none;font-weight: 500;font-size: 15px;color: var(--nacht);position: relative}.header__nav a::after{content: "";position: absolute;left: 14px;right: 14px;bottom: 8px;height: 2px;background: var(--geel);transform: scaleX(0);transform-origin: left;transition: transform var(--t-ui) var(--ease)}.header__nav a:hover::after,.header__nav a[aria-current="page"]::after{transform: scaleX(1)}.header__cta{display: none}.header__cta .btn{min-height: 44px;font-size: 15px}@media (min-width: 960px){.header__nav{display: block}.header__cta{display: block}.menu-toggle{display: none !important}}
